required <- c("config/case.yml", "config/sources.csv", "data/candidates.csv", "data/review.csv", "data/corpus.csv", "data/concepts.csv", "data/retrieval_diagnostics.csv")
stopifnot(all(file.exists(required)))
cfg <- yaml::read_yaml("config/case.yml")
stopifnot(cfg$start_year == 1991, cfg$end_year == 2026, cfg$validation_max_valid_per_source == 5)
candidates <- read.csv("data/candidates.csv", stringsAsFactors = FALSE, check.names = FALSE)
needed <- c("document_id","title","publication_date","year","language","institution","families","document_type","source_page","document_url","format","relevance_excerpt","matched_case_terms","matched_concepts","retrieval_method","retrieved_at","review_status")
stopifnot(all(needed %in% names(candidates)))
if (nrow(candidates)) stopifnot(!anyDuplicated(candidates$canonical_url), all(grepl("^https://", candidates$document_url)), all(candidates$review_status %in% c("pending","retain","include","exclude","needs_review")))
cat(sprintf("Smoke check passed (%d candidates).\n", nrow(candidates)))
